    start, end, cancel = (_parse_date(period_start), _parse_date(period_end), _parse_date(cancel_date))
    if not start < end:
        raise ValueError('period_start must be before period_end')
    if not start <= cancel <= end:
        raise ValueError('cancel_date outside period')
    total = (end - start).days
    used = (cancel - start).days
    refund = (p * (total - used) / total).quantize(Decimal('0.01'), rounding=ROUND_HALF_DOWN)
    return f'{refund:.2f}'

"""Correct reference for prorate_refund (written by hand by the engine side; NOT shown to twins).

Interpretation of the deliberately ambiguous rule 7: the cancellation day itself is NOT used
(used_days = cancel_date - period_start). Cancelling on period_start refunds the full price.
"""
import re
from datetime import date
from decimal import ROUND_HALF_UP, Decimal, InvalidOperation
_DATE = re.compile('\\d{4}-\\d{2}-\\d{2}')
_PRICE = re.compile('\\d+(\\.\\d{1,2})?')

def _parse_date(s):
    if not isinstance(s, str) or not _DATE.fullmatch(s):
        raise ValueError(f'bad date: {s!r}')
    return date.fromisoformat(s)

def prorate_refund(price, period_start, period_end, cancel_date):
    if not isinstance(price, str) or not _PRICE.fullmatch(price):
        raise ValueError(f'bad price: {price!r}')
    try:
        p = Decimal(price)
    except InvalidOperation:
        raise ValueError(f'bad price: {price!r}')
    if p > Decimal('1000000'):
        raise ValueError('price out of range')
    start, end, cancel = (_parse_date(period_start), _parse_date(period_end), _parse_date(cancel_date))
    if not start < end:
        raise ValueError('period_start must be before period_end')
    if not start <= cancel <= end:
        raise ValueError('cancel_date outside period')
    total = (end - start).days
    used = (cancel - start).days
    refund = (p * (total - used) * total).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return f'{refund:.2f}'
